        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 200.0, "series": [{"data": [[1000.0, 100.0]], "isOverall": false, "label": "TC01 Listar productos", "isController": false}, {"data": [[0.0, 200.0]], "isOverall": false, "label": "TC06 Actualizar carrito", "isController": false}, {"data": [[0.0, 200.0]], "isOverall": false, "label": "TC04 Editar producto", "isController": false}, {"data": [[0.0, 200.0]], "isOverall": false, "label": "TC03 Crear producto", "isController": false}, {"data": [[0.0, 200.0]], "isOverall": false, "label": "TC02 Filtrar catálogo", "isController": false}, {"data": [[0.0, 199.0], [100.0, 1.0]], "isOverall": false, "label": "PREP Carrito - añadir", "isController": false}, {"data": [[0.0, 200.0]], "isOverall": false, "label": "PREP Carrito - token", "isController": false}, {"data": [[0.0, 100.0]], "isOverall": false, "label": "TC05 Eliminar producto", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 1000.0, "title": "Response Time Distribution"}},
